 import Button from './components/Button.svelte';import List from './components/List.svelte';import Row from './components/Row.svelte';import Cover from './components/Cover.svelte';import Sheet from './components/Sheet.svelte';import StepDots from './components/StepDots.svelte';import WeekDots from './components/WeekDots.svelte';import TabBar from './components/TabBar.svelte';import Keyboard from './components/Keyboard.svelte';import VerseText from './components/VerseText.svelte';
 import {tokenize,firstLetters,maskWords,allowance,grade,transition,schedule,gentleCap,dueItems} from './engine';
 import {starters,documents,lookupReference} from './content';
 import {openStore,persist,api,mergeItems,defaults,today,type LocalState,type Item} from './store';
 let data=$state<LocalState>({items:[],events:[],settings:{...defaults},queue:[]});
 let ready=$state(false),tab=$state<string>(location.pathname===ui.c152?ui.c041:ui.c043),detail=$state<string>(ui.c019),practice=$state<Item|null>(null),session=$state<string[]>([]),position=$state(0),slips=$state<number[]>([]),result=$state(false),learned=$state(false),shortcut=$state(false),review=$state(false),message=$state<string>(ui.c019),error=$state<string>(ui.c019),busy=$state(false),account=$state<any>(null),config=$state<any>({}),recovery=$state<string>(ui.c019),recoverInput=$state<string>(ui.c019),confirmDelete=$state(false),welcome=$state(false),addMode=$state<string>(ui.c079),reference=$state<string>(ui.c019),translation=$state<string>(ui.c086),customTitle=$state<string>(ui.c019),customText=$state<string>(ui.c019),found=$state<any[]>([]),selectedDoc=$state<string>(ui.c019),nextDue=$state<string>(ui.c019);
 const live=$derived(data.items.filter(i=>!i.deleted));
 const calendarDays=(date:string)=>Math.max(0,Math.round((Date.parse(today())-Date.parse(date))/86400000)||0);
