 const detailItems=$derived(live.filter(i=>i.collection===detail));
 const weekCount=$derived(data.settings.days.filter(d=>{const date=new Date(d+ui.c153);const now=new Date();now.setDate(now.getDate()-((now.getDay()+6)%7));now.setHours(0,0,0,0);return date>=now}).length);
 function theme(){document.documentElement.dataset.theme=data.settings.theme}
