 async function sync(){const userAtStart=account;if(!userAtStart)return;if(syncing){syncAgain=true;return}syncing=true;try{const items=$state.snapshot(data.items),events=$state.snapshot(data.events);let out:any;const batches=Math.max(1,Math.ceil(items.length/500),Math.ceil(events.length/1000));for(let n=0;n<batches;n++)out=await api(ui.c154,{items:items.slice(n*500,(n+1)*500),events:events.slice(n*1000,(n+1)*1000),settings:$state.snapshot(data.settings)});
 if(account!==userAtStart)return;data.items=mergeItems(data.items,out.items||[]);if(out.settings&&Number(out.settings.updatedAt)>data.settings.updatedAt)data.settings={...defaults,...out.settings};theme();const map=new Map(data.events.map(e=>[e.id,e]));for(const e of out.events||[])map.set(e.id,e);data.events=[...map.values()];data.queue=[];await persist($state.snapshot(data));if(!message||message===ui.c155||message===ui.c156)message=ui.c155}catch(e){message=ui.c156}finally{syncing=false;if(syncAgain){syncAgain=false;if(account)void sync()}}}

 async function attempt(fn:()=>Promise<void>){busy=true;error=ui.c019;try{await fn()}catch(e){error=e instanceof Error?e.message:String(e)}finally{busy=false}}
 onMount(()=>{void attempt(async()=>{data=await openStore();data.settings={...defaults,...data.settings};ready=true;theme();welcome=daysAway>=7&&rampDay>=7;try{config=await api(ui.c157);const out=await api(ui.c158);account=out.user||out.account||null;if(out.recoveryCode)recovery=out.recoveryCode;if(account)await sync()}catch{} });const online=()=>{if(account)void sync()};window.addEventListener(ui.c159,online);return()=>window.removeEventListener(ui.c159,online)});
 function navigate(to:string){addTarget=ui.c019;tab=to;detail=ui.c019;error=ui.c019;message=ui.c019}
 async function add(items:any[],collectionId?:string){for(const item of items){if(!live.some(i=>i.id===item.id))data.items.push({...item,collection:addTarget||collectionId||item.collection||ui.c160,step:1,learned:false,due:new Date().toISOString(),createdAt:new Date().toISOString(),updatedAt:Date.now()})}data.queue.push(crypto.randomUUID());await save();message=ui.c161}
 async function addStarter(s:any){await add(s.items,s.id);detail=s.id;tab=ui.c044}
 function begin(items:Item[]){session=items.map(i=>i.id);loadNext()}
 function loadNext(){const id=session.shift();if(!id){practice=null;learned=false;result=false;return}const item=data.items.find(i=>i.id===id)!;practice=item;review=item.learned;shortcut=false;learned=false;position=0;slips=[];result=false;nextDue=ui.c019}
 function key(key:string,peek=false){if(!practice||result||learned||position>=words.length)return;const wrong=peek||!firstLetters(words[position]).includes(key.toLowerCase());if(wrong&&mask[position])slips.push(position);position++;if(position>=words.length)result=true}
 function physical(e:KeyboardEvent){if(practice&&!result&&!learned&&!e.metaKey&&!e.ctrlKey&&!e.altKey&&/^[a-z0-9]$/i.test(e.key)){e.preventDefault();key(e.key)}}
 async function finish(){if(!practice)return;const now=new Date(),attemptStep=practice.step,wasReview=review,hiddenCount=hidden;let fsrsLog:any=null;const g=grade(slips.length,hiddenCount);const out=transition(attemptStep,slips.length,hiddenCount,shortcut);if(review){const scheduled=schedule(practice.card,g,now);fsrsLog=scheduled.log;practice.card=scheduled.card;practice.due=new Date(scheduled.card.due).toISOString();nextDue=new Date(practice.due).toLocaleDateString(undefined,{month:ui.c162,day:ui.c163});if(g===ui.c164){practice.learned=false;practice.step=3;review=false}else{learned=true}}else{practice.step=out.step;practice.learned=out.learned;if(out.learned){practice.learnedAt=now.toISOString();const scheduled=schedule(practice.card,g,now);fsrsLog=scheduled.log;practice.card=scheduled.card;practice.due=new Date(scheduled.card.due).toISOString();nextDue=new Date(practice.due).toLocaleDateString(undefined,{month:ui.c162,day:ui.c163});learned=true}}
 practice.updatedAt=Date.now();const event={id:crypto.randomUUID(),itemId:practice.id,at:now.toISOString(),slips:slips.length,hidden:hiddenCount,grade:g,mode:wasReview?ui.c165:ui.c166,step:attemptStep,fsrsLog};data.events.push(event);data.queue.push(event.id);if(!data.settings.days.includes(today()))data.settings.days.push(today());data.settings.lastActive=today();await save();result=false;position=0;slips=[];shortcut=false}
 async function signup(){await attempt(async()=>{const options=await api(ui.c167,{displayName:data.settings.name});const response=await startRegistration({optionsJSON:options.options||options});const out=await api(ui.c168,{response,name:data.settings.name});account=out.user||out.account;recovery=out.recoveryCode||ui.c019;await sync()})}
 async function signin(){await attempt(async()=>{const options=await api(ui.c169,{});const response=await startAuthentication({optionsJSON:options.options||options});const out=await api(ui.c170,{response});account=out.user||out.account;await sync()})}
 async function recover(){await attempt(async()=>{const out=await api(ui.c171,{code:recoverInput});account=out.user||out.account;recovery=out.recoveryCode||ui.c019;recoverInput=ui.c019;await sync()})}
 async function signout(){await attempt(async()=>{await api(ui.c172,{});account=null;message=ui.c173})}
 async function exportData(){await attempt(async()=>{const out=account?await api(ui.c174):$state.snapshot(data);const a=document.createElement(ui.c175);a.href=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:ui.c176}));a.download=ui.c177;a.click();URL.revokeObjectURL(a.href);message=ui.c178})}
