 async function enablePush(){await attempt(async()=>{if(!account)throw Error(ui.c182);if(!(ui.c183 in window)||!(ui.c184 in window))throw Error(ui.c185);const permission=await Notification.requestPermission();if(permission!==ui.c186)throw Error(ui.c187);const reg=await navigator.serviceWorker.ready;const raw=config.vapidPublicKey||config.vapid; if(!raw)throw Error(ui.c188);const key=Uint8Array.from(atob(raw.replace(/-/g,ui.c189).replace(/_/g,ui.c190)),c=>c.charCodeAt(0));const sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});await api(ui.c191,{subscription:sub.toJSON()});data.settings.pushEnabled=true;await save();message=ui.c192})}
 async function disablePush(){await attempt(async()=>{const reg=await navigator.serviceWorker.ready;await (await reg.pushManager.getSubscription())?.unsubscribe();await api(ui.c191,{subscription:null});data.settings.pushEnabled=false;await save()})}
