 async function own(){await attempt(async()=>{if(!customTitle.trim()||!customText.trim())throw Error(ui.c194);await add([{id:crypto.randomUUID(),title:customTitle.trim(),text:customText.trim(),collection:ui.c160}]);customTitle=ui.c019;customText=ui.c019;navigate(ui.c044)})}
