 <h3>{ui.c111}</h3>{#if account}<p>{ui.c112}</p><Button secondary onclick={()=>void signout()}>{ui.c113}</Button>{:else}<p>{ui.c114}</p><Button onclick={()=>void signup()} disabled={busy}>{ui.c115}</Button><Button secondary onclick={()=>void signin()} disabled={busy}>{ui.c116}</Button>{#if config.google}<Button secondary onclick={()=>location.href=ui.c117}>{ui.c118}</Button>{/if}<label>{ui.c119}<input bind:value={recoverInput} autocomplete="off"/></label><Button secondary onclick={()=>void recover()} disabled={busy||!recoverInput}>{ui.c120}</Button>{/if}
 <h3>{ui.c121}</h3><p>{ui.c122}</p><Button secondary onclick={()=>void (data.settings.pushEnabled?disablePush():enablePush())}>{data.settings.pushEnabled?ui.c123:ui.c124}</Button>{#if data.settings.pushEnabled}<Button secondary onclick={()=>void attempt(async()=>{await api(ui.c125,{});message=ui.c126})}>{ui.c127}</Button>{/if}
 <Button secondary onclick={()=>void exportData()}>{ui.c128}</Button>{#if account}<Button secondary onclick={()=>confirmDelete=true}>{ui.c129}</Button>{/if}<small>{ui.c130}</small></div>
